create table if not exists public.demo_settings (id boolean primary key default true check(id),weekly_rate numeric(6,4) not null default 0.06 check(weekly_rate between 0 and 0.10),withdrawals_paused boolean not null default false,pause_message text not null default 'Demo withdrawal testing is active',updated_by uuid references public.profiles(id),updated_at timestamptz not null default now());
insert into public.demo_settings(id) values(true) on conflict(id) do nothing;
alter table public.demo_settings enable row level security;
create policy "demo settings signed-in read" on public.demo_settings for select to authenticated using(true);
create policy "demo settings admin update" on public.demo_settings for update to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.update_demo_controls(p_rate numeric,p_paused boolean,p_message text) returns public.demo_settings language plpgsql security definer set search_path=public as $$ declare result public.demo_settings; begin if not public.is_admin() then raise exception 'Admin access required'; end if; update public.demo_settings set weekly_rate=p_rate,withdrawals_paused=p_paused,pause_message=coalesce(nullif(trim(p_message),''),'Demo withdrawal testing is active'),updated_by=auth.uid(),updated_at=now() where id=true returning * into result; insert into public.admin_audit_logs(admin_id,action,entity_type,entity_id,metadata) values(auth.uid(),'demo_controls_updated','demo_settings','global',jsonb_build_object('weekly_rate',p_rate,'withdrawals_paused',p_paused,'message',p_message)); return result; end $$;
grant execute on function public.update_demo_controls(numeric,boolean,text) to authenticated;
